#!/usr/bin/env node
/**
 * Post Sterling Intelligence Briefing (Evening Edition) to Telegram
 * 
 * Usage:
 *   export TELEGRAM_BOT_TOKEN="your-token"
 *   export TELEGRAM_CHAT_ID="your-chat-id"
 *   node tmp/send-sterling-briefing-evening.js
 */

const fs = require('fs');
const path = require('path');

const BRIEFING_FILE = path.join(__dirname, '../logs/sterling-telegram-evening-2026-03-02.txt');

async function postToTelegram() {
  const botToken = process.env.TELEGRAM_BOT_TOKEN;
  const chatId = process.env.TELEGRAM_CHAT_ID;

  if (!botToken || !chatId) {
    console.error('❌ Error: Missing required environment variables');
    console.error('   Set TELEGRAM_BOT_TOKEN and TELEGRAM_CHAT_ID');
    process.exit(1);
  }

  if (!fs.existsSync(BRIEFING_FILE)) {
    console.error(`❌ Error: Briefing file not found: ${BRIEFING_FILE}`);
    process.exit(1);
  }

  const message = fs.readFileSync(BRIEFING_FILE, 'utf8');

  console.log('📤 Sending Sterling Briefing (Evening) to Telegram...');
  console.log(`📱 Chat ID: ${chatId}`);
  console.log(`📄 Message length: ${message.length} chars`);
  console.log('');

  try {
    const response = await fetch(
      `https://api.telegram.org/bot${botToken}/sendMessage`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          chat_id: chatId,
          text: message,
          disable_web_page_preview: true,
        }),
      }
    );

    const result = await response.json();

    if (!result.ok) {
      console.error('❌ Telegram API error:', result.description);
      console.error('   Error code:', result.error_code);
      process.exit(1);
    }

    console.log('✅ Briefing sent successfully!');
    console.log(`📨 Message ID: ${result.result.message_id}`);
    console.log('');
    console.log('🔗 Check your Telegram app to verify delivery');
  } catch (error) {
    console.error('❌ Failed to send message:', error.message);
    process.exit(1);
  }
}

postToTelegram();

